136	/**
137	 * Extends the {@code AbstractRequestInterceptorClient} class and provides an
138	 * implementation for federation of YARN RM and scaling an application across
139	 * multiple YARN SubClusters. All the federation specific implementation is
140	 * encapsulated in this class. This is always the last intercepter in the chain.
141	 */
142	public class FederationClientInterceptor
143	    extends AbstractClientRequestInterceptor {
144	
145	  /*
146	   * TODO YARN-6740 Federation Router (hiding multiple RMs for
147	   * ApplicationClientProtocol) phase 2.
148	   *
149	   * The current implementation finalized the main 4 calls (getNewApplication,
150	   * submitApplication, forceKillApplication and getApplicationReport). Those
151	   * allow us to execute applications E2E.
152	   */
153	
154	  private static final Logger LOG =
155	      LoggerFactory.getLogger(FederationClientInterceptor.class);
156	
157	  private int numSubmitRetries;
158	  private Map<SubClusterId, ApplicationClientProtocol> clientRMProxies;
159	  private FederationStateStoreFacade federationFacade;
160	  private Random rand;
161	  private RouterPolicyFacade policyFacade;
162	  private RouterMetrics routerMetrics;
163	  private ThreadPoolExecutor executorService;
164	  private final Clock clock = new MonotonicClock();
165	  private boolean returnPartialReport;
166	
167	  @Override
168	  public void init(String userName) {
169	    super.init(userName);
170	
171	    federationFacade = FederationStateStoreFacade.getInstance();
172	    rand = new Random(System.currentTimeMillis());
173	
174	
175	    int numThreads = getConf().getInt(
176	        YarnConfiguration.ROUTER_USER_CLIENT_THREADS_SIZE,
177	        YarnConfiguration.DEFAULT_ROUTER_USER_CLIENT_THREADS_SIZE);
178	    ThreadFactory threadFactory = new ThreadFactoryBuilder()
179	        .setNameFormat("RPC Router Client-" + userName + "-%d ").build();
180	
181	    BlockingQueue workQueue = new LinkedBlockingQueue<>();
182	    this.executorService = new ThreadPoolExecutor(numThreads, numThreads,
183	        0L, TimeUnit.MILLISECONDS, workQueue, threadFactory);
184	
185	    final Configuration conf = this.getConf();
186	
187	    try {
188	      policyFacade = new RouterPolicyFacade(conf, federationFacade,
189	          this.federationFacade.getSubClusterResolver(), null);
190	    } catch (FederationPolicyInitializationException e) {
191	      LOG.error(e.getMessage());
192	    }
193	
194	    numSubmitRetries =
195	        conf.getInt(YarnConfiguration.ROUTER_CLIENTRM_SUBMIT_RETRY,
196	            YarnConfiguration.DEFAULT_ROUTER_CLIENTRM_SUBMIT_RETRY);
197	
198	    clientRMProxies =
199	        new ConcurrentHashMap<SubClusterId, ApplicationClientProtocol>();
200	    routerMetrics = RouterMetrics.getMetrics();

          + subClusterId.getId());
    }

    long stopTime = clock.getTime();
    routerMetrics.succeededAppsRetrieved(stopTime - startTime);
    return response;
  }

  /**
   * The Yarn Router will forward the request to all the Yarn RMs in parallel,
   * after that it will group all the ApplicationReports by the ApplicationId.
   *
   * Possible failure:
   *
   * Client: identical behavior as {@code ClientRMService}.
   *
   * Router: the Client will timeout and resubmit the request.
   *
   * ResourceManager: the Router calls each Yarn RM in parallel. In case a
   * Yarn RM fails, a single call will timeout. However the Router will
   * merge the ApplicationReports it got, and provides a partial list to
   * the client.
   *
   * State Store: the Router will timeout and it will retry depending on the
   * FederationFacade settings - if the failure happened before the select
   * operation.
   */
  @Override
  public GetApplicationsResponse getApplications(GetApplicationsRequest request)
      throws YarnException, IOException {
    if (request == null) {
      routerMetrics.incrMultipleAppsFailedRetrieved();
      RouterServerUtil.logAndThrowException(
          "Missing getApplications request.",
          null);
    }
    long startTime = clock.getTime();
    Map<SubClusterId, SubClusterInfo> subclusters =
        federationFacade.getSubClusters(true);
    ClientMethod remoteMethod = new ClientMethod("getApplications",
        new Class[] {GetApplicationsRequest.class}, new Object[] {request});
    Map<SubClusterId, GetApplicationsResponse> applications;

    try {
      applications = invokeConcurrent(subclusters.keySet(), remoteMethod,
          GetApplicationsResponse.class);

    } catch (Exception ex) {
      routerMetrics.incrMultipleAppsFailedRetrieved();
      LOG.error("Unable to get applications due to exception.", ex);
      throw ex;
    }
    long stopTime = clock.getTime();
    routerMetrics.succeededMultipleAppsRetrieved(stopTime - startTime);
    // Merge the Application Reports
    return RouterYarnClientUtils.mergeApplications(applications.values(),
        returnPartialReport);
  }

  @Override
  public GetClusterMetricsResponse getClusterMetrics(
      GetClusterMetricsRequest request) throws YarnException, IOException {
    long startTime = clock.getTime();
    Map<SubClusterId, SubClusterInfo> subclusters =
        federationFacade.getSubClusters(true);
    ClientMethod remoteMethod = new ClientMethod("getClusterMetrics",
        new Class[] {GetClusterMetricsRequest.class}, new Object[] {request});
    Map<SubClusterId, GetClusterMetricsResponse> clusterMetrics;

    try {
      clusterMetrics = invokeConcurrent(subclusters.keySet(), remoteMethod,
          GetClusterMetricsResponse.class);

    } catch (Exception ex) {
      routerMetrics.incrGetClusterMetricsFailedRetrieved();
      LOG.error("Unable to get cluster metrics due to exception.", ex);
      throw ex;
    }

    long stopTime = clock.getTime();
    routerMetrics.succeededGetClusterMetricsRetrieved(stopTime - startTime);
    return RouterYarnClientUtils.merge(clusterMetrics.values());
  }

  <R> Map<SubClusterId, R> invokeConcurrent(ArrayList<SubClusterId> clusterIds,
      ClientMethod request, Class<R> clazz) throws YarnException, IOException {
    List<Callable<Object>> callables = new ArrayList<>();
    List<Future<Object>> futures = new ArrayList<>();
    Map<SubClusterId, IOException> exceptions = new TreeMap<>();
    for (SubClusterId subClusterId : clusterIds) {
      callables.add(new Callable<Object>() {
        @Override
        public Object call() throws Exception {
          ApplicationClientProtocol protocol =
              getClientRMProxyForSubCluster(subClusterId);
          Method method = ApplicationClientProtocol.class
              .getMethod(request.getMethodName(), request.getTypes());
          return method.invoke(protocol, request.getParams());
        }
      });
    }
    Map<SubClusterId, R> results = new TreeMap<>();
    try {
      futures.addAll(executorService.invokeAll(callables));
      for (int i = 0; i < futures.size(); i++) {
        SubClusterId subClusterId = clusterIds.get(i);
        try {
          Future<Object> future = futures.get(i);
          Object result = future.get();
          results.put(subClusterId, clazz.cast(result));
        } catch (ExecutionException ex) {
          Throwable cause = ex.getCause();
          LOG.debug("Cannot execute {} on {}: {}", request.getMethodName(),
              subClusterId.getId(), cause.getMessage());
          IOException ioe;
          if (cause instanceof IOException) {
            ioe = (IOException) cause;
          } else if (cause instanceof YarnException) {
            throw (YarnException) cause;
          } else {
            ioe = new IOException(
                "Unhandled exception while calling " + request.getMethodName()
                    + ": " + cause.getMessage(), cause);
          }
          // Store the exceptions
          exceptions.put(subClusterId, ioe);
        }
      }
      if (results.isEmpty() && !clusterIds.isEmpty()) {
        SubClusterId subClusterId = clusterIds.get(0);
        IOException ioe = exceptions.get(subClusterId);
        if (ioe != null) {
          throw ioe;
        }
      }
    } catch (InterruptedException e) {
      throw new YarnException(e);
    }
    return results;
  }

  <R> Map<SubClusterId, R> invokeConcurrent(Collection<SubClusterId> clusterIds,
      ClientMethod request, Class<R> clazz) throws YarnException, IOException {
    ArrayList<SubClusterId> clusterIdList = new ArrayList<>(clusterIds);
    return invokeConcurrent(clusterIdList, request, clazz);
  }

